import json
def w(n,o): json.dump(o,open('dup_work/airspecs/%s.json'%n,'w',encoding='utf8'),ensure_ascii=False)
w('csn',{"airline":"China Southern","alcohol":{"checked":"22 November 2026","answer":"China Southern bans alcohol in carry-on unless you bought it in the terminal's sterile area after security. In checked baggage, drinks up to 24% alcohol are unrestricted, drinks above 24% and up to 70% are limited to 5 litres net per person, and anything above 70% is not accepted.","sections":[{"h":"🍷 What China Southern says about alcohol","p":"From the China Southern General Conditions of Carriage for Passenger and Baggage (sections 4.5.6, 6.2.9 and 6.3.4.7), read on 22 November 2026. Cabin liquids are covered by its separate carry-on liquids rule.","table":{"head":["Question","China Southern rule"],"rows":[["Alcohol in carry-on","Prohibited, except alcohol bought in the sterile area of the terminal, which may go on board if it meets the carry-on and alcohol rules"],["Checked, 24% alcohol or less","Unrestricted"],["Checked, above 24% up to 70%","No more than 5 litres net per person"],["Above 70%, or homemade distilled spirits","Not allowed as baggage"],["Packaging when checked","Must meet civil aviation transport rules"],["Drinking your own","Not allowed aboard; only alcohol provided by China Southern may be drunk"]]},"list":["<strong>Not on the page:</strong> the Conditions do not say what happens to duty-free alcohol bought at an overseas airport; the carry-on FAQ says China Southern follows local regulations for those liquids."]}],"faq":[["Can I bring a bottle of alcohol in my China Southern carry-on?","Not unless you bought it in the sterile area of the terminal after security. Alcohol from elsewhere goes in checked baggage."],["How much alcohol can I check on China Southern?","Up to 24% alcohol is unrestricted; above 24% and up to 70% is limited to 5 litres net per person; above 70% is not accepted."],["Can I drink my own alcohol on a China Southern flight?","No. Passengers may drink only the alcohol China Southern provides on board."]],"sources":[["https://www.csair.com/cts-products/cts/fastdfs/20260626/3edae764dd49418582ef740225391b1a.pdf","China Southern &mdash; General Conditions of Carriage for Passenger &amp; Baggage"],["https://www.csair.com/sg/en/tourguide/faq/baggage/ssxdxlxz.shtml","China Southern &mdash; Carry-on Baggage FAQ"]]}})
w('cea',{"airline":"China Eastern","alcohol":{"checked":"22 November 2026","answer":"China Eastern allows drinks up to 24% alcohol without limit, and 5 litres per person of drinks from 24% to 70% in checked baggage; above 70% is prohibited. Alcohol must go in checked baggage, except what you buy in the passenger terminal, which may go on board.","sections":[{"h":"🍷 What China Eastern says about alcohol","p":"From the China Eastern General Conditions for Transportation of Passengers and Baggage (July 2026), sections 5.4.4 and 7.2.3.8, read on 22 November 2026.","table":{"head":["Question","China Eastern rule"],"rows":[["24% alcohol or less","No restriction in carry-on or checked baggage"],["Above 24% up to 70%","Containers of at most 5 litres, and 5 litres in total in checked baggage per passenger"],["Above 70%","Prohibited in carry-on and checked baggage"],["Where to carry it","Check it in; only alcohol bought in the passenger terminal may be carried on board"],["Checked packaging","Retail packaging with a full, clear label; strong sealed outer packaging; China Eastern may ask for a liability waiver"],["Stricter local law","China Eastern follows stricter laws at the departure, transit or destination place"],["Drinking your own","Not permitted in the cabin; only alcohol served by China Eastern"]]},"list":["<strong>Not on the page:</strong> the Conditions give no separate rule for duty-free alcohol bought at an overseas airport."]}],"faq":[["How much alcohol can I take on China Eastern?","Up to 24% alcohol has no limit; 24% to 70% is limited to 5 litres per passenger in checked baggage; above 70% is prohibited."],["Can I carry alcohol in the cabin on China Eastern?","Only alcohol bought in the passenger terminal. Other alcohol must be checked."],["Can I drink my own alcohol on China Eastern?","No. Passengers may drink only alcohol served on board by China Eastern."]],"sources":[["https://www.ceair.com/global/en_static/Announcement/TravelTips/dsGeneralCondition/chinaEasternLuggageRules/domesticRules/202201/W020260724485859129374.pdf","China Eastern &mdash; General Conditions for Transportation of Passengers and Baggage (July 2026)"]]}})
